solutionCode:
#[derive(Debug, PartialEq)]
pub enum Estado {
    Novo,
    Riscado,
    Quebrado,
}

pub fn estado_da_colo() -> Estado {
    Estado::Novo
}

pub fn estado_da_vitrine() -> Estado {
    Estado::Riscado
}

pub fn estado_do_fundo_do_bau() -> Estado {
    Estado::Quebrado
}

testsCode:
use desafio::estado_da_colo;
use desafio::estado_da_vitrine;
use desafio::estado_do_fundo_do_bau;
use desafio::Estado;

#[test]
fn testa_o_estado_da_colo() {
    assert_eq!(estado_da_colo(), Estado::Novo);
}

#[test]
fn testa_o_estado_da_vitrine() {
    assert_eq!(estado_da_vitrine(), Estado::Riscado);
}

#[test]
fn testa_o_estado_do_fundo_do_bau() {
    assert_eq!(estado_do_fundo_do_bau(), Estado::Quebrado);
}
